# Simple map format
# MAP <mapId>
# GROUND <defaultSpritePath>
# OBJECT <id> <type> <x> <y> <spritePath> <solid(0|1)>
# TRIGGER <id> <x> <y> <width> <height> <eventName>

MAP 0001_TestMap
GROUND Assets/Sprites/Environment/Forest/forest_ground.png

OBJECT rock_01 scenery -192 -64 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_02 scenery -128 -64 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_03 scenery 64 -128 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_04 scenery 192 -64 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_05 scenery -192 128 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_06 scenery -64 128 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_07 scenery 128 128 Assets/Sprites/Environment/Forest/forest_rock.png 1
OBJECT rock_08 scenery 256 192 Assets/Sprites/Environment/Forest/forest_rock.png 1

TRIGGER spawn_area -80 -80 160 160 Trigger_SpawnArea
TRIGGER north_path_to_forest -64 -260 220 120 Load_0001_Forest
